def build_RCE_F_Schlick():
    t = _tree('RCE_F_Schlick')
    g = G(t)
    v0 = g.inp('f0', False)
    v1 = g.inp('u', False)
    v2 = g.math('SUBTRACT', 1, v1)
    v3 = g.math('MULTIPLY', v2, v2)
    v4 = g.math('MULTIPLY', v2, v3)
    v5 = g.math('MULTIPLY', v4, v3)
    v6 = g.math('SUBTRACT', 1, v0)
    v7 = g.math('MULTIPLY', v6, v5)
    v8 = g.math('ADD', v7, v0)
    g.out_('ret', v8, False)


